      "schlussText": null,
      "spielerNachPause": null,
      "kontext": "Mike prüft den Zugang, verkeilt ihn und schreibt erst von der Werkbank aus. Der kleine verschlossene Warteraum liegt nebenan; er ist nicht identisch mit der Werkstatt.",
      "autorenNotiz": "Werkstatttür besitzt keinen Schlossbedarf. Betonstein hält ausschließlich diesen Zugang offen und wird nicht als tragbarer Gegenstand erfunden.",
