      "schlussText": null,
      "spielerNachPause": null,
      "kontext": "Ethan hält nur Mikes Jackensaum fest, nicht seine Hände. Beide stehen noch verdeckt hinter dem Mauervorsprung; Richard ruft vom oberen Zugang und beginnt keinen körperlichen Angriff. Mike schickt wenige kurze Zeilen mit einer freien Hand.",
