      "titel": "Der bearbeitete Entwurf der Einladung",
      "beschreibung": "Auf einer gefalteten Seite stehen Michael Reed, seine Heimatstadt und mehrere Absätze des tatsächlich in Akt A gezeigten Einladungsbriefs. Die Produktion übernimmt dessen Formulierungen wörtlich. Zwischen den Absätzen stehen handschriftliche Änderungen und eine zweite, knappere Korrekturschrift. Darunter liegt Mikes zuletzt aktualisierter öffentlicher Suchbeitrag mit dem Hinweis, dass er seit seinem achtzehnten Lebensjahr nach seiner Herkunft sucht. Der Briefentwurf ist ein Arbeitsblatt, kein amtlicher Abstammungsnachweis. Hände halten nur die Papierkanten; es sind keine Verletzungen sichtbar.",
