      "beschreibung": "Dauer 23 Sekunden. Vollständige Textfassung: [Ein Schlüssel oder Metallbeschlag klirrt, zwei Schritte auf Holz.] Richard, ruhig: „Lass den Wagen. Ich nehme jetzt die Tür am Waschraum. Halt ihn von dem niedrigen Gang fern.“ Evelyn: „Und Ethan?“ Richard: „Bleibt da. Ich habe nichts anderes gesagt.“ [Eine Tür wird aufgezogen. Richard sagt im Weggehen: „Michael hört schon zu, wenn man ruhig mit ihm redet.“ Drei Schritte, dann tiefes Pumpenbrummen. Ende.]",
